import{_ as s,o as p,c as n,a3 as r}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"讲解：自配平产线和自适应装置","description":"","frontmatter":{"translationSource":{"title":"讲解：自配平产线和自适应装置","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=MSyCxO1yMtqlXdUCG6Utsc","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/explanation-automatically-balanced-production-lines-and-adaptive-devices"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/explanation-automatically-balanced-production-lines-and-adaptive-devices"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/explanation-automatically-balanced-production-lines-and-adaptive-devices"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/explanation-automatically-balanced-production-lines-and-adaptive-devices"}]]},"headers":[],"relativePath":"zh/explanation-automatically-balanced-production-lines-and-adaptive-devices.md","filePath":"zh/page-MSyCxO1yMtqlXdUCG6Utsc.md"}'),e={name:"zh/explanation-automatically-balanced-production-lines-and-adaptive-devices.md"};function l(t,a,c,o,d,k){return p(),n("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="讲解-自配平产线和自适应装置" tabindex="-1">讲解：自配平产线和自适应装置 <a class="header-anchor" href="#讲解-自配平产线和自适应装置" aria-label="Permalink to &quot;讲解：自配平产线和自适应装置&quot;">​</a></h1><blockquote><p>源页面 ID：<code>MSyCxO1yMtqlXdUCG6Utsc</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=MSyCxO1yMtqlXdUCG6Utsc" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>该页面目前作为视频文案/脚本</p><p><span id="source-block-TpyJfHRw0zbnYOTULA9OaX"></span></p><h2 id="素材预览" tabindex="-1">素材预览 <a class="header-anchor" href="#素材预览" aria-label="Permalink to &quot;素材预览&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-403d77df278b7ae4.q90-d1663eb5e22f9e26.webp" alt="讲解：自配平产线和自适应装置"></p><div class="logistics-image-caption" data-source-block="kHsqAVmcDeYRDvfuWXnuG5"><p>封面</p></div><p><span class="mark-grey"><em>不管你们听不听 1:左边塞了失真的二进制数字，转换成十进制后再转换成ASCII码是 Hello World 2:最强基建下的英文小字意思是最大调度券产出 3:左侧的黄条被我贴了箭头假装是传送带——盒猫</em></span></p><p><span id="source-block-JHB9yrgA7h2xtO0t0QlxBz"></span></p><h2 id="脚本草稿02-2026-09-20-23-26" tabindex="-1">脚本草稿02（2026.09.20 23:26） <a class="header-anchor" href="#脚本草稿02-2026-09-20-23-26" aria-label="Permalink to &quot;脚本草稿02（2026.09.20 23:26）&quot;">​</a></h2><p><span id="source-block-mmdylS8XHjIFfm2cfDiV6w"></span></p><h3 id="_0-为什么要自动配平" tabindex="-1">0. 为什么要自动配平 <a class="header-anchor" href="#_0-为什么要自动配平" aria-label="Permalink to &quot;0. 为什么要自动配平&quot;">​</a></h3><p>在1.4版本伊始，气体工业的加入带来两位大人：</p><p><strong>&lt;（°0°）&gt;</strong><span class="mark-red"><strong>灼铜大人</strong></span><strong>和</strong><span class="mark-green"><strong>重息壤大人</strong></span><strong>\\（°0°）/</strong></p><p>我的天哪<span class="mark-red">灼铜大人</span>售价70调度券，超凡脱俗的复杂工艺震撼人心！</p><p>【一段展示灼铜工艺复杂性的长难句神秘文本作为画面】</p><p>经过各路up各显神通的计算，</p><p>我们现在知道所谓最高产能就是多多地做<span class="mark-red">灼铜大人</span>和<span class="mark-green">重息壤大人</span>，加上两位前朝显贵<span class="mark-orange">中容武陵电池大人</span>和<span class="mark-blue">芽针针剂，呃，小人</span>，</p><p>最好是一点<span class="mark-red">铜</span>和<span class="mark-green">息壤</span>都不要剩下，<span class="mark-orange">源矿</span>和<span class="mark-blue">蓝铁</span>也是一样。</p><p>为了做到这一点，up们先是给出了14.4<span class="mark-red">灼铜零件</span>24<span class="mark-green">重息壤</span>的配平组合，然后给出了更极限的14.2<span class="mark-red">灼铜零件</span>26<span class="mark-green">重息壤</span>的配平组合，后者已经非常非常接近理论解！</p><p>呃但是我只是一个普通玩家，比起压榨产能我想说：</p><p>【口播】</p><p>要吃药怎么办？</p><p>矿没开齐怎么办？</p><p>不想拉净水节点怎么办？</p><p>谷地没开超库存传输怎么办？</p><p>【画面】</p><p><strong>原料都配平掉了，自己要吃的优质芽针针剂没原料做了怎么办？</strong></p><p><strong>我的矿没开齐，不够产线用怎么办？</strong></p><p><strong>我不想拉净水节点，这破暗管谁爱拉谁拉，但是极限产能必须要用怎么办？</strong></p><p><strong>我的谷地没拉满，没有超库存传输......</strong></p><p>欸，普通玩家还要求这多，那为什么不用剩下原料更多的低产量产线呢？</p><p>那咋了，我就是想利用掉所有原料又高产还要能满足这些要求，不行吗？</p><p><strong>于是经过我们的努力，自动配平产线就此诞生。</strong></p><hr><p><span id="source-block-1faCu7aoIRuLPFVhDwffDu"></span></p><h3 id="_1-局部自动配平" tabindex="-1">1. 局部自动配平 <a class="header-anchor" href="#_1-局部自动配平" aria-label="Permalink to &quot;1. 局部自动配平&quot;">​</a></h3><p>一上来就理解四种原料自动配平成四种产物也太难了，我们先只制作灼铜和重息壤。</p><p>【画面：灼铜零件、重息壤的复杂配方先展示】</p><p>虽然<span class="mark-red">灼铜零件</span>和<span class="mark-green">重息壤</span>的配方十分复杂，但是先不要被配方吓到，归根结底，它们终究只是使用同样的两种原料：<span class="mark-red"><strong>铜</strong></span>和<span class="mark-green"><strong>息壤</strong></span>。</p><p>让我们忽略掉中间的弯弯绕绕吧。</p><p>【动效：复杂配方淡出，只留下“铜+息壤→ 灼铜 / 铜+息壤→ 重息壤”的简化图】</p><p>现在请想象这样的一个账号：</p><ul><li><p><span class="mark-red">铜</span>产量 <u><strong>325</strong></u>/min；</p></li><li><p><span class="mark-green">息壤和息壤气</span>产量拉满；</p></li></ul><p>【画面：铜和息壤以柱状图形式呈现，如下图，并附上虚拟报表】</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-94b783219ced502b.q90-80a1cacb3b1a20ca.webp" alt="讲解：自配平产线和自适应装置"></p><p>我们只做<span class="mark-red">灼铜</span>和<span class="mark-green">重息壤</span>，此时的产出是这样的：</p><p>【动效：表达灼铜和重息壤配平，用柱状图+虚拟报表的形式呈现。先把上图的息壤和赤铜块图标隐藏，然后把下图覆盖上去】</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-242b204df8c9af15.q90-e688fb355386c397.webp" alt="讲解：自配平产线和自适应装置"></p><p>现在把剩余矿点都连上，<span class="mark-red">铜</span>产量提高到 510/min。</p><p>【动效：柱状图里新增加的铜用虚线框标出】</p><p>多出来的这些<span class="mark-red">铜</span>怎么消耗掉呢？如果我们增加<span class="mark-green">重息壤</span>产量，</p><p><span class="mark-grey">编造数据：325息壤 325赤铜</span></p><p>【动效：保持重息壤柱高亮，重息壤柱增加灼铜柱降低，此过程中息壤柱始终被完全占据，赤铜柱自然地减少了】</p><p>欸不对不对，怎么<span class="mark-red">铜</span>消耗还变少了！那增加<span class="mark-red">灼铜</span>产量呢？</p><p>【动效：保持灼铜柱高亮，灼铜柱增加重息壤柱降低，此过程中息壤柱始终被完全占据，赤铜柱自然地增加直至占满代表新增加的铜的虚线框部分】</p><p>欸对了对了，这样一来多出来的<span class="mark-red">铜</span>就全部被消耗掉了。</p><p><strong>也就是说为了配平多出来的</strong><span class="mark-red"><strong>铜</strong></span><strong>，</strong><span class="mark-red"><strong>灼铜</strong></span><strong>产量要增加而</strong><span class="mark-green"><strong>重息壤</strong></span><strong>产量则随之减少。（考虑单独占据画面）</strong></p><p>【动效：当前柱状图中用更浅的颜色高亮在此时的柱状图时原来的灼铜柱长度和重息壤长度作为对比，高亮的时机与“灼铜产量要增加”和“重息壤则随之减少”对齐】</p><p>但是要自动配平的话，得让产线随着<span class="mark-red">铜</span>增加自发地增加<span class="mark-red">灼铜</span>产量、减少<span class="mark-green">重息壤</span>产量。</p><p>这该怎么做到呢？这里先给出结论：</p><p>【这两句话可以考虑单独占据画面】【或者配一个体现这种供料顺序的动图】</p><ul><li><p><span class="mark-green"><strong>息壤</strong></span><strong>：先喂饱</strong><span class="mark-red"><strong>灼铜产线</strong></span><strong>，剩下的给</strong><span class="mark-green"><strong>重息壤产线</strong></span><strong>。</strong></p></li><li><p><span class="mark-red"><strong>铜</strong></span><strong>：先喂饱</strong><span class="mark-green"><strong>重息壤产线</strong></span><strong>，剩下的给</strong><span class="mark-red"><strong>灼铜产线</strong></span><strong>。</strong></p></li></ul><hr><p><span id="source-block-UZH2II0Mn5LYYrBxTMtjDT"></span></p><h3 id="_2-供料顺序不能反" tabindex="-1">2. 供料顺序不能反 <a class="header-anchor" href="#_2-供料顺序不能反" aria-label="Permalink to &quot;2. 供料顺序不能反&quot;">​</a></h3><p>为什么必须是“<span class="mark-green">息壤</span>先喂饱<span class="mark-red">灼铜产线</span>，<span class="mark-red">铜</span>先喂饱<span class="mark-green">重息壤产线</span>”？我们一个个来看。</p><p><span id="source-block-jpwYyc2eYmxphzWFQvcrCp"></span></p><h4 id="如果灼铜产线的息壤不够" tabindex="-1">如果<span class="mark-red">灼铜产线</span>的<span class="mark-green">息壤</span>不够 <a class="header-anchor" href="#如果灼铜产线的息壤不够" aria-label="Permalink to &quot;如果&lt;span class=&quot;mark-red&quot;&gt;灼铜产线&lt;/span&gt;的&lt;span class=&quot;mark-green&quot;&gt;息壤&lt;/span&gt;不够&quot;">​</a></h4><p>让我们回到上一节的例子中，刚连上矿点的时候：</p><p>【画面：新增加的铜已用虚线框标出的柱状图】</p><p>尝试增加<span class="mark-red">灼铜</span>产量，但是<span class="mark-green">息壤</span>供应不够，增加到一半卡住了！</p><p>【动效：保持灼铜柱高亮，灼铜柱增加重息壤柱降低，此过程中息壤柱始终被完全占据，赤铜柱自然地增加，但是加到一半停止了，此时让在息壤柱的灼铜柱闪烁红光表示供应不足】</p><p>这时我们可以看到，多出来的<span class="mark-red">铜</span>没有被全部消耗掉。</p><p>【动效：铜柱没有占满虚线框部分——剩余的虚线框部分闪烁红光表示没有被消耗掉/利用干净】</p><p><strong>于是我们得到结论：想利用掉增加的</strong><span class="mark-red"><strong>铜</strong></span><strong>，必须先用</strong><span class="mark-green"><strong>息壤</strong></span><strong>喂饱</strong><span class="mark-red"><strong>灼铜产线</strong></span><strong>，保证它</strong><span class="mark-green"><strong>息壤</strong></span><strong>足够。</strong></p><p><span id="source-block-BJVYySQVQWYcEh1CFYZE7H"></span></p><h4 id="如果重息壤产线的铜不够" tabindex="-1">如果<span class="mark-green">重息壤产线</span>的<span class="mark-red">铜</span>不够 <a class="header-anchor" href="#如果重息壤产线的铜不够" aria-label="Permalink to &quot;如果&lt;span class=&quot;mark-green&quot;&gt;重息壤产线&lt;/span&gt;的&lt;span class=&quot;mark-red&quot;&gt;铜&lt;/span&gt;不够&quot;">​</a></h4><p>类似的，我们增加<span class="mark-green">息壤</span>，然后尝试增加<span class="mark-green">重息壤</span>产量。</p><p>【动效：保持重息壤柱高亮，重息壤柱增加灼铜柱降低，此过程中铜柱始终被完全占据，息壤柱自然地增加，但是加到一半停止了，此时让在铜柱的重息壤柱闪烁红光表示供应不足】</p><p>结果是类似的，因为<span class="mark-green">重息壤产线</span>的<span class="mark-red">铜</span>供应不足，所以我们没花光增加的<span class="mark-green">息壤</span>。</p><p>【动效：息壤柱剩余的虚线框部分闪烁红光表示没有被消耗掉/利用干净】</p><p>那么结果和<span class="mark-red">灼铜产线</span>缺<span class="mark-green">息壤</span>的情形非常类似了，想要利用掉增加的<span class="mark-green">息壤</span>，必须先用<span class="mark-red">铜</span>喂饱<span class="mark-green">重息壤产线</span>，保证它<span class="mark-red">铜</span>足够。</p><p>【画面：上一节的结论<a href="/endfield-skydoc/zh/explanation-automatically-balanced-production-lines-and-adaptive-devices">讲解：自配平产线和自适应装置</a>】</p><p>到这里我们已经回答了为什么必须是“<span class="mark-green">息壤</span>先喂饱<span class="mark-red">灼铜产线</span>，<span class="mark-red">铜</span>先喂饱<span class="mark-green">重息壤产线</span>”，但是我们给出的结论还有一部分——“剩下的<span class="mark-green">息壤</span>给<span class="mark-green">重息壤产线</span>，剩下的<span class="mark-red">铜</span>给<span class="mark-red">灼铜产线</span>”</p><p>【画面：仅有重息壤柱子的柱状图，铜柱空缺的部分仍是用虚线框表示】</p><p>我们试想如果只做<span class="mark-green">重息壤</span>，那<span class="mark-green">重息壤产线</span>自己当然用不掉这么多<span class="mark-red">铜</span>，</p><p>【动效：高亮铜柱空缺部分的虚线框】</p><p>这些剩余的<span class="mark-red">铜</span>就需要让<span class="mark-red">灼铜产线</span>来消耗掉。</p><p>【动效：柱状图中开始出现灼铜柱并不断增加，直至铜柱被填满】</p><p>可以看出，如果我们想要所有原料被利用干净，就一定需要一条产线来消耗掉剩余的原料。<br> 方便起见，这种专门吃“其他产线用剩下的某种原料”的产线，我们叫它：</p><p><strong>末端产线（<strong>可以考虑单独占据画面</strong>）</strong></p><p>那么<span class="mark-red">灼铜产线</span>可以称为<span class="mark-red">铜</span>这一原料的末端产线，也就是说<span class="mark-red">灼铜产线</span>是消耗<span class="mark-red">铜</span>的产线里最末尾的产线。</p><p>【画面：仅有灼铜柱子的柱状图，息壤柱空缺的部分仍是用虚线框表示】</p><p>类似的，只做<span class="mark-red">灼铜</span>用不掉的<span class="mark-green">息壤</span>则是由<span class="mark-green">重息壤产线</span>来消耗掉，那么<span class="mark-green">重息壤产线</span>可以称为<span class="mark-green">息壤</span>这一原料的末端产线。</p><p>【动效：柱状图中开始出现重息壤柱并不断增加，直至息壤柱被填满】</p><hr><p><span id="source-block-4QOXSXxHhkUYMnNs9qh1dD"></span></p><h3 id="_3-更多原料" tabindex="-1">3. 更多原料！？ <a class="header-anchor" href="#_3-更多原料" aria-label="Permalink to &quot;3. 更多原料！？&quot;">​</a></h3><p>【画面：原本的铜和息壤柱状图，但是坐标轴上加入了源矿和蓝铁】</p><p>截至目前，我们处理了两种原料<span class="mark-green"></span><span class="mark-red">铜 </span><span class="mark-green">息壤 </span>两种产物 <span class="mark-red">灼铜 </span><span class="mark-green">重息壤</span></p><p>但是1.5版本我们还有另外两种原料 <span class="mark-orange">源矿</span> <span class="mark-blue">蓝铁 </span>另外两种产物<span class="mark-blue"></span><span class="mark-orange">中电</span><span class="mark-blue"> 小药</span>（用小字标注 小药上小字标注芽针针剂 中电上用小字标注中容武陵电池）</p><p>现在我们把他们加进来：</p><p>【动效：从“铜、息壤 → 灼铜、重息壤”扩展到“铜、息壤、源矿、蓝铁 → 灼铜、重息壤、中电、小药”】</p><p>是不是一下子眼花缭乱了？别心急，别忘了我们的目的是让所有原料都被消耗，所以每一种原料都需要一条产线来消耗掉其他产线用剩下的部分——<strong>也就是说，我们可以让原料和末端一一对应！</strong></p><p>可能有细心的观众已经发现了，在之前的讲解中我们会用特定颜色来表示原料和产物，其实相同的颜色就表示原料与之对应的末端：</p><p><span class="mark-red">铜-灼铜 </span><span class="mark-green">息壤-重息壤 </span><span class="mark-orange">源矿-中电 </span><span class="mark-blue">蓝铁-小药</span></p><p>在之前的讲解中我们已经知道了消耗<span class="mark-red">铜</span>为主的<span class="mark-red">灼铜产线</span>是<span class="mark-red">原料铜</span>的末端产线，消耗<span class="mark-green">息壤</span>为主的<span class="mark-green">重息壤产线</span>是<span class="mark-green">原料息壤</span>的末端产线，</p><p>那么，消耗<span class="mark-orange">源矿</span>为主的<span class="mark-orange">中电产线</span>就是<span class="mark-orange">原料源矿</span>的末端产线，消耗<span class="mark-blue">蓝铁</span>为主的<span class="mark-blue">小药产线</span>就是<span class="mark-blue">原料蓝铁</span>的末端产线！</p><p>【画面：中电柱、小药柱随着讲解依次高亮】</p><p>同样的，和<span class="mark-red">灼铜</span><span class="mark-green">重息壤</span>类似，为了让<span class="mark-orange">中电产线</span>可以顺利吃完<span class="mark-orange">源矿</span>以及让小药产线可以顺利吃完蓝铁，我们需要让<span class="mark-orange">中电产线</span>除了<span class="mark-orange">源矿</span>之外的其他原料都供应充足，也就是中电产线所需要的<span class="mark-green">息壤</span>和蓝铁都被优先供满，</p><p>【动效：高亮息壤柱和蓝铁柱中的中电柱】</p><p>而<span class="mark-blue">小药产线</span>只吃<span class="mark-blue">蓝铁</span>，所以就没有什么需要供应充足的地方了</p><p>我们可以把这些整理成一张表格：</p><table tabindex="0"><thead><tr><th>原料</th><th>先保证谁</th><th>剩余给谁</th><th>末端</th></tr></thead><tbody><tr><td><span class="mark-red">铜</span></td><td><span class="mark-green">重息壤</span></td><td><span class="mark-red">灼铜</span></td><td><span class="mark-red">灼铜</span></td></tr><tr><td><span class="mark-green">息壤</span></td><td><span class="mark-red">灼铜 </span><span class="mark-orange">中电</span></td><td><span class="mark-green">重息壤</span></td><td><span class="mark-green">重息壤</span></td></tr><tr><td><span class="mark-orange">源矿</span></td><td>无</td><td><span class="mark-orange">中电</span></td><td><span class="mark-orange">中电</span></td></tr><tr><td><span class="mark-blue">蓝铁</span></td><td><span class="mark-orange">中电</span></td><td><span class="mark-blue">小药</span></td><td><span class="mark-blue">小药</span></td></tr></tbody></table><hr><p><span id="source-block-WL13fhHXFTCR8WbVOO0loD"></span></p><h3 id="_4-更多样的末端" tabindex="-1">4. 更多样的末端 <a class="header-anchor" href="#_4-更多样的末端" aria-label="Permalink to &quot;4. 更多样的末端&quot;">​</a></h3><p>【画面：铜、息壤、源矿、蓝铁 → 灼铜、重息壤、中电、小药】</p><p>那末端只能是一种产物吗？当然不是！</p><p>比如在 1.5 智能最大毛产中，当<span class="mark-red">赫铜</span>未满仓时，<span class="mark-red">赫铜</span>和<span class="mark-red">灼铜</span>产出保持 1:2。这时<span class="mark-red">铜末端</span>就不是单纯的<span class="mark-red">灼铜</span>，而是<span class="mark-red">“</span><span class="mark-red"><strong>1:2 的赫铜和灼铜”</strong></span><strong>。</strong></p><p>【动效：灼铜零件变成赫铜零件和灼铜零件的组合图标】</p><p>其实可以把多种产物组合成的末端看成是一个自定义配方的产物，那就和前面的单产物作为末端的情形一样了。</p><p>引入了组合产物作为末端后，我们能得到更多种产物了！或许这条路的尽头，我们能抵达<strong>全物品-自动配平</strong>的终极......</p><hr><p><span id="source-block-mA63XxzuxdkTwf9hxAfQO5"></span></p><h3 id="_5-小结" tabindex="-1">5. 小结 <a class="header-anchor" href="#_5-小结" aria-label="Permalink to &quot;5. 小结&quot;">​</a></h3><p>【画面：铜、息壤、源矿、蓝铁 → 灼铜、重息壤、中电、小药】（或者淡化后作为背景？）</p><p>让我们来整理下目前的内容：</p><p>整套自动配平，只需要记住两点：（考虑让这两行字占据画面）</p><ol><li><p>一种原料对应一种末端，就像是<span class="mark-red">铜</span>和<span class="mark-green">息壤</span>分别对应能消耗完<span class="mark-red">铜</span>的<span class="mark-red">灼铜</span>和能消耗完<span class="mark-green">息壤</span>的<span class="mark-green">重息壤</span>。当然了，末端可以是组合的产物，像是上一节提到的<span class="mark-red">“1:2 的赫铜和灼铜”</span>作为<span class="mark-red">铜末端</span>。</p></li><li><p>每种原料都先喂饱其他用到这重原料产线，然后剩下的原料才给末端，比如<span class="mark-red">铜</span>先喂饱<span class="mark-green">重息壤产线</span>确保<span class="mark-green">重息壤产线</span>能顺利消耗完<span class="mark-green">息壤</span>然后剩下的<span class="mark-red">铜</span>给到作为<span class="mark-red">铜末端</span>的<span class="mark-red">灼铜产线</span>——五个字来说就是“<strong>先供非末端</strong>”，今后的涉及到自动配平的内容中我们将反复引用这五个字。</p></li></ol><p>（关于中间产物分离芯，情况会稍显复杂，我们决定讲文字讲解放在简介，在之后可能专门出一期讲解视频）</p><p><span class="mark-grey">#关于分离芯，不妨在简介中讲解：<br> 根据视频所学，可以说无论是灼铜还是重息壤，为了完全消耗铜/息壤不能有其他原料的不足，此时把分离芯看成一种特殊的原料，如此一来为了让铜/息壤被灼铜/重息壤完全消耗自然需要充足供应的分离芯，我们不必思考分离芯由什么原料制成——吗？<br> 在目前的配方中，倒是可以直接这么认为。但是我想愿意来简介阅读文字的朋友应该不满足于如此粗糙的表述，所以让我对重息壤的配方稍加修改让上述表述不能成立：<br> （原配方）息壤+分离芯→（修改后配方）铜+分离芯<br> 那如果此时我们放任重息壤的分离芯充足的话，它将直接和同样使用分离芯的灼铜产线争抢分离芯——如果重息壤争抢过于多的分离芯，灼铜就会受制于变少的分离芯导致灼铜无法消耗干净其他产线用剩的铜（有趣的是，争抢过于少的分离芯=灼铜得到的分离芯充足。或者说灼铜优先被供满分离芯，剩下分离芯被重息壤消耗，于是重息壤成为分离芯的末端，分离芯成为息壤的末端，等价为重息壤正确地作为息壤末端）。归根结底，此时的重息壤没有正确地成为息壤的末端，所以一种正确的做法是不给重息壤产线供给分离芯而是供给其他产线用剩下的息壤和充足的铜，让重息壤所用的分离芯的生产也处于重息壤的产线中。<br> 嘛，总而言之就是谨记自动配平是靠末端产线正确地发挥末端作用而实现的，这个结论是基本符合数学规律的，无论是让分离芯保持供应充足还是让分离芯生产耦合进末端产线都只不过是为了在不同的情形下让实际产线符合“先供非末端”的手段之一罢了（没错，我所举的例子中给出的方案也并不是唯一的选择），<br> 如果你看到这里应该也能明白为什么视频中没有讲作为中间产物的分离芯了——多少是有点让人头晕晕了。但是分离芯又是设计具体产线时不能绕开的玩意，于是我们将这段文字放在简介里，希望可以帮到想要自己理解/设计自动配平的你（比心）（孩子们别信，只是创作团队咕咕了《中间产物与自动配平》这一讲解视频）（万一呢，万一我们真有余力做出来呢）</span></p><p><span class="mark-grey">#关于分离芯，不妨在简介中讲解：（ko鸟简略版本）</span></p><ol><li><p><span class="mark-grey">由于分离芯并不是最终要拿去卖的产物，所以先让铜和息壤做分离芯，把它塞爆仓一定是一个有效的方案。为什么呢？</span></p></li><li><p><span class="mark-grey">分离芯爆仓时，其数量维持不变，所以灼铜和重息壤消耗的分离芯，会直接等价地“透传”到息壤和铜的消耗上，此时整个问题就退化成了铜、息壤直接配平灼铜和重息壤的问题。</span></p></li><li><p><span class="mark-grey">在此基础上应用视频中的学到的知识即可。</span></p></li></ol><p>【画面：三个产线视频的封面和省略号】</p><p>“<strong>先供非末端</strong>”就是自动配平的铁律了，而在我们的产线讲解视频中将会实地讲解各种各样的布局是如何实现“先供非末端”的，像是1.5这期的空仓-加压（此时高亮1.5这期视频的封面）、1.6这两期的空仓-直连/满仓-溢流/满仓-震荡（此时高亮1.6这两期视频封面），敬请期待。</p><p><span class="mark-grey">#倒不是说要着急地把1.6的封面做出来，可以用黑底白字代指一下。</span></p><p><span class="mark-grey">#（如采用简化版本的第六小节）“</span><span class="mark-grey"><strong>先供非末端</strong></span><span class="mark-grey">”就是自动配平的铁律了，接下来我们用游戏中的具体结构来实现“</span><span class="mark-grey"><strong>先供非末端</strong></span><span class="mark-grey">”。</span></p><hr><p><span id="source-block-kqVBhL14xHrfvLosPFsx1U"></span></p><h3 id="_6-回到实际的产线中去-已废弃" tabindex="-1"><span class="mark-grey">6. 回到实际的产线中去（已废弃）</span> <a class="header-anchor" href="#_6-回到实际的产线中去-已废弃" aria-label="Permalink to &quot;&lt;span class=&quot;mark-grey&quot;&gt;6. 回到实际的产线中去（已废弃）&lt;/span&gt;&quot;">​</a></h3><p><span class="mark-grey"><strong>以下是盒猫的版本：</strong></span></p><p><strong>1.取货口加压</strong></p><p>那如何实现这一点呢？</p><p>我们先从加压讲起，也就是给产线添加额外的取货口。</p><p>拿1.5版本最大毛产的灼铜产线举例</p><p>我们先复习一下刚刚学过的知识点：</p><p><span class="mark-red">灼铜产线 </span>不是 <span class="mark-green">息壤</span>的末端产线，所以<span class="mark-red">灼铜产线</span>用的<span class="mark-green">息壤</span>被优先供应</p><p>【展示灼铜产线的息壤液的加压】</p><p>【用框框中灼铜产线的息壤加压部分】</p><p>此处版本1:在这里我们灼铜产线提供液化息壤的模块额外添加取货口来尽量保证这里以满速运行</p><p>此处版本2:在这里，给灼铜产线提供液化息壤的模块需要30/min的息壤来满速运行，在产速足够的情况下只需要一个息壤取货口即可满足要求。但是在空仓情况下，一个取货口不足以达到30/min的要求，于是我们可以额外添加取货口来尽量保证这里以满速运行。这便是通过取货口加压来实现优先供应息壤。</p><p>在其他部分也是同理</p><p>比如还是在灼铜产线中，我们可以用同样的办法给分离芯产线部分的息壤加压</p><p>【展示分离芯产线的息壤的加压】</p><p>【动效同上】</p><p>在重息壤产线里因为</p><p>“<span class="mark-green">重息壤产线</span>不是<span class="mark-red">铜</span>的末端产线，所以<span class="mark-green">重息壤产线</span>用的<span class="mark-red">铜</span>被优先供应”</p><p>需要给分离芯产线部分的铜加压</p><p>【展示分离芯产线的铜的加压】</p><p>【动效同上】</p><p>在中武产线中 又因为</p><p><span class="mark-orange">“中武产线</span>不是<span class="mark-green">息壤</span>或者<span class="mark-blue">蓝铁</span>的末端产线，所以<span class="mark-orange">中武产线</span>用的<span class="mark-green">息壤</span>和<span class="mark-blue">蓝铁</span>被优先供应”</p><p>需要给壤晶（做电池需要的材料——标注在视频内 <span class="mark-grey">（防止有小天才晕晕）</span>）部分的息壤还有蓝铁粉产线的蓝铁矿加压</p><p>【展示壤晶产线的息壤的加压】【展示蓝铁打粉的蓝铁矿的加压】</p><p><span class="mark-blue">小药产线</span>除了<span class="mark-blue">蓝铁</span>不需要其他原料了，所以它只是<span class="mark-blue">蓝铁</span>的末端产线，不会被优先供应。</p><p>————————————————————————</p><p><strong>2.溢流</strong></p><p>除了加压以外，我们还能通过溢流器来构建优先级</p><p>具体原理可以参考这个视频（贴个百亿视频的链接）</p><p>————————————————————————</p><p>还有很多很多其他的办法可以做到优先供应的效果比如满仓溢流等</p><p><span class="mark-grey"><strong>以下是言的版本：</strong></span></p><p>（画面：登录过程）现在让我们打开游戏，看看具体的产线（斯改的1.5最强基建）是如何实现自动配平的（我想着要不着两句话就一直放在视频中，画面的旁边？<a href="/endfield-skydoc/zh/explanation-automatically-balanced-production-lines-and-adaptive-devices">讲解：自配平产线和自适应装置</a>）：</p><ul><li><p>灼铜产线不是<span class="mark-green">息壤</span>的末端产线，所以<span class="mark-red">灼铜产线</span>用的<span class="mark-green">息壤</span>被优先供满<br> 【展示灼铜产线的息壤液的加压和分离芯产线的息壤的加压】<br><span class="mark-grey">欸等等，为什么说用更多取货口可以做到优先供应？（显示息壤液配方）可以看到扩容反应池要满速生产液化息壤需要使用30/min（2s一个）的息壤，同时一个取货口最多只能输出30/min（2s一个）息壤，这里有两个取货口连接了这一个扩反，保证即使别的地方有使用息壤导致一个取货口输出不满30/min息壤也能供满扩反需要的30/min息壤，也就是</span><span class="mark-grey"><strong>“</strong></span><span class="mark-red"><strong>灼铜产线</strong></span><strong>用的</strong><span class="mark-green"><strong>息壤</strong></span><strong>被优先供满</strong><span class="mark-grey"><strong>”</strong></span></p></li><li><p><span class="mark-green">重息壤产线</span>不是<span class="mark-red">铜</span>的末端产线，所以<span class="mark-green">重息壤产线</span>用的<span class="mark-red">铜</span>被优先供满<br> 【展示分离芯产线的铜的加压】</p></li><li><p><span class="mark-orange">中电产线</span>不是<span class="mark-green">息壤</span>或者<span class="mark-blue">蓝铁</span>的末端产线，所以<span class="mark-orange">中电产线</span>用的<span class="mark-green">息壤</span>和<span class="mark-blue">蓝铁</span>被优先供满<br> 【展示中电产线的息壤的加压和蓝铁打粉产线的蓝铁的加压】</p></li><li><p><span class="mark-blue">小药产线</span>除了<span class="mark-blue">蓝铁</span>不需要其他原料了，所以它只是<span class="mark-blue">蓝铁</span>的末端产线，没有需要优先供满的地方）</p></li></ul><p>不要被增加取货口保证空仓时的优先供应的思路限制了！有很多很多的办法可以做到优先供应的效果：（我感觉这里可以稍微讲得详细一点）</p><p>洪炉直连溢流以优先供给息壤；满仓震荡；先加压一条带，用这条带溢流；还有我们所未涉及的方案......</p><p><span class="mark-grey"><strong>以下是Zirunwang的版本：</strong></span></p><p>那如何实现我们“优先供给”的目标呢</p><p>在消耗大于产出的时候，各个取货口会轮流输出，平均分配有限的资源</p><p>那如果让两个取货口合二为一，这条线的权重就是其他出货口的两倍</p><p>所以，只要给[这几条]产线多加几个取货口，就可以了！</p><hr><p><span id="source-block-2fr5Ewnj0NrSCQ63hqxmOR"></span></p><h3 id="_6-回到实际的产线中去-简化版" tabindex="-1"><span class="mark-grey">6. 回到实际的产线中去（简化版）</span> <a class="header-anchor" href="#_6-回到实际的产线中去-简化版" aria-label="Permalink to &quot;&lt;span class=&quot;mark-grey&quot;&gt;6. 回到实际的产线中去（简化版）&lt;/span&gt;&quot;">​</a></h3><p>我们先考虑最简单的蓝铁，使用蓝铁的产线有中电产线和小药产线，其中小药产线负责保证蓝铁被消耗完，所以小药是蓝铁的末端，我们需要先供满<span class="mark-grey">（”</span>不是蓝铁的末端产线的<span class="mark-grey">“ 盒-感觉这部分可以省略，有点拗口）</span>中电产线。</p><p>图片：蓝矿取货口→精炼炉→通电协议箱→粉碎机→壤晶→中电 通电协议箱→蓝铁取货口→小药</p><p>这样一来，只有中电产线供满了蓝铁块，蓝铁才会溢出到箱子里进入仓库，然后做成小药。</p><p><span class="mark-grey">（已废弃）但是这样的结构也带来了麻烦，它要求蓝铁精炼和电池线相连。蓝铁精炼占地不大配方简单，那倒也没什么大问题，但是息壤的产线可是天有洪炉那一大片啊。</span></p><p><span class="mark-grey">（已废弃）息壤的非末端产线还多，也就是说作为息壤非末端产线的灼铜产线和中电产线都要拖着天有洪炉！那就非常臃肿了，尤其是灼铜产线本来就十分庞大，还要拖家带口地和天有洪炉相连——有没有不那么赤石的办法？（说实话感觉有点不太对，要解释臃肿其实应该要解释中电的壤晶和电池可以分离而灼铜产线的中间产物几乎都是液气所以不能分离，然后解释灼铜产线很容易一不小心就变成要解释好不容易略过的分离芯，那就很麻瓜了，对观众中的初学者徒增思考负担；与此同时不解释臃肿的话，稍微懂一点基建但又理解不深的观众就会非常疑惑：为什么臃肿，明明中电产线可以分离壤晶生产和中电生产啊。也就是说我感觉有点两头堵了）</span></p><p>当然了，事实上还有相当多的办法来实现我们所需要的“先供xx再供xx”，而之后我们的产线发布视频中都会附带“如何做到先供非末端”的讲解。例如在大家比较熟悉的1.5版本最大毛产的视频（画面给到1.5版本最大毛产的封面）所采用的“空仓-加压”这一办法我们在后续会补发一个讲解视频进行讲解。之后将发布的迭代后产线则采用了“满仓-震荡”、“满仓-溢流”、“空仓-直连”、“定量取货口”<span class="mark-grey">（直接说“更多办法”？盒-我觉得直接写这几种名词就行，毕竟正常人也不需要真正意义上的在这一部分理解这些词，只需要知道有这几种东西，也不需要记住，没有负担）</span>，届时也会同步有讲解视频，希望观众们能通过我们的设计学习到更多基建思路并运用到自己的基建之中！</p><p><span id="source-block-ctjg208JA1DNTLwW4qG980"></span></p><h3 id="_7-为什么支持自行添加产线" tabindex="-1">7. 为什么支持自行添加产线？ <a class="header-anchor" href="#_7-为什么支持自行添加产线" aria-label="Permalink to &quot;7. 为什么支持自行添加产线？&quot;">​</a></h3><p>在视频的结尾我们来讲点简单的放松一下吧，</p><p>还记得视频开头所说的“普通玩家需求”吗？【展示对应视频片段】</p><p>到目前为止我们所讲述的大部分内容都是自动配平产线如何实现自动配平。但如果手动加了一条新产线，自动配平产线会怎么处理这个新产线的原料消耗？</p><p>其实可以把自行添加的产线所消耗的原料当成没有进入自动配平系统，就像没开的矿点一样。去掉这部分被使用的原料后，自动配平产线会把剩余的原料尽数转化为我们所希望得到的产物。</p><p><strong>于是，既要又要的狂想，就这样实现了。</strong></p><p>但是目前的自动配平事实上仍有极限，让我们把这个作为思考题：<br> 自行添加产线到什么程度，或者说什么样的原料比例，自动配平产线将无法将剩余原料完全配平？</p><p>（等待10s播放片尾）</p><hr><p>片尾：</p><p>那么产线的自动配平/自适应讲解到这里就结束了</p><p>让我们在下一期“装置的自适应”再会！</p><p>【画面：成员签名】（待议）</p><p><span id="source-block-uSPzt91Tkj3UXVGuFFiNbE"></span></p><h2 id="脚本草稿01-2026-09-20-14-44" tabindex="-1">脚本草稿01（2026.09.20 14:44） <a class="header-anchor" href="#脚本草稿01-2026-09-20-14-44" aria-label="Permalink to &quot;脚本草稿01（2026.09.20 14:44）&quot;">​</a></h2><p><span class="mark-red">灼铜</span><span class="mark-green">重息壤</span><span class="mark-orange">中电</span><span class="mark-blue">小药</span></p><p><span class="mark-red">铜</span><span class="mark-green">息壤</span><span class="mark-orange">源矿</span><span class="mark-blue">蓝铁</span></p><p><span id="source-block-YxiPu1ktesxNu2Ai80cDnk"></span></p><h3 id="初步讲解——局部的自动配平" tabindex="-1">初步讲解——局部的自动配平 <a class="header-anchor" href="#初步讲解——局部的自动配平" aria-label="Permalink to &quot;初步讲解——局部的自动配平&quot;">​</a></h3><p>让我们先从这次自适应基建的骨架，灼铜零件与重息壤配平赤铜块和息壤讲起（也许可以带上图标）</p><p>虽然灼铜零件和重息壤的配方较为复杂（展示原配方），但是本质还是使用息壤和铜（此处贴动效：复杂配方简化为仅铜壤的简化配方）</p><p>要理解自动配平，我们不妨先从更简单更局部的情形讲起：现在我们有一个铜产量360/min、息壤和息壤气产量拉满的账号（拿出该铜壤下的柱状图）现在我们去把剩余的矿点都连上使得铜产量达到510/min（柱状图中用虚线框出新开的铜）为了配平这些铜，我们需要增加灼铜产量（让灼铜的铜壤在柱状图上闪烁一下或者其他的高亮方式），而增加的灼铜零件将用掉更多的息壤（类似地高亮灼铜用的息壤），重息壤的产量也随之降低（类似地高亮重息壤的铜壤）（呃这些高亮时其实可以在边界出标箭头？）最终我们靠通过增加灼铜零件减少重息壤来配平新增的铜产量（旧态到新态的柱状图变化动图）</p><p>那么该怎么让产线随着铜产量增加，自发地增加灼铜产量和降低重息壤产量呢？我们先给出结论：息壤先保证灼铜产线的息壤供应充足，剩余息壤供给到重息壤产线；铜先保证重息壤产线的息壤供应充足，剩余铜供给到灼铜产线</p><p><span id="source-block-QOxgDyvlkq06FPNwl39jag"></span></p><h3 id="为什么不能非末端供料不足-非末端供料充足" tabindex="-1">为什么不能非末端供料不足/非末端供料充足 <a class="header-anchor" href="#为什么不能非末端供料不足-非末端供料充足" aria-label="Permalink to &quot;为什么不能非末端供料不足/非末端供料充足&quot;">​</a></h3><p>接下来我们从灼铜产线入手，假如灼铜产线的息壤供给不足，会发生什么？让我们回到上一小节的例子我们增加灼铜减少重息壤（仿照上一小节的高亮按顺序高亮，呃具体怎么弄再议）（旧态到新态转化到半路因为息壤不足停止了）可以看到有铜没有被利用上！那么同样的，我们想象一个铜拉满但是息壤气矿还没有连的账号，如果不能保证重息壤的铜供应充足，会发生什么呢（和灼铜类似的动画）可以看到有息壤没有利用上。综上所述，用铜更多的灼铜产线需要保证息壤供应充足，用息壤更多的重息壤产线需要保证铜供应充足。</p><p><span id="source-block-BUsTuWsaMRCCb0IXWgrJ5q"></span></p><h3 id="末端不供料充足-末端使用剩余原料" tabindex="-1">末端不供料充足/末端使用剩余原料 <a class="header-anchor" href="#末端不供料充足-末端使用剩余原料" aria-label="Permalink to &quot;末端不供料充足/末端使用剩余原料&quot;">​</a></h3><p>到这里，我们一开始给出的结论“息壤先保证灼铜产线的息壤供应充足，剩余息壤供给到重息壤产线；铜先保证重息壤产线的息壤供应充足，剩余铜供给到灼铜产线”已经完成一半了，剩余息壤供给到重息壤产线和剩余铜供给到灼铜产线该怎么理解呢？我们先从剩余铜给到灼铜产线入手，假设我们先不做灼铜只做重息壤（只有重息壤的柱状图）可以看到我们还有很多铜没有利用，为了利用这些重息壤用剩的铜我们需要增加灼铜减少重息壤（对应动图）也就是说，除了重息壤产线要用到的铜剩余的铜都最终流向了灼铜产线！类似的，我们假设只做灼铜然后增加重息壤以利用剩余的息壤（对应动图）可以看到灼铜的息壤被充分供应时剩下的息壤就流向重息壤产线</p><p><span id="source-block-XeOpz3nTAVJxnNSQ3EDvQV"></span></p><h3 id="更多的末端-原料" tabindex="-1">更多的末端-原料 <a class="header-anchor" href="#更多的末端-原料" aria-label="Permalink to &quot;更多的末端-原料&quot;">​</a></h3><p>接下来让我们将这种原理拓展到更多原料！（铜壤-灼重动态变为铜壤源铁-灼重电药）是不是一下子头晕了？其实还是一样的，我们来看新加入的电池和芽针针剂（高亮中电和小药）中电用的源矿多所以我们供满它除了源矿的其他原料需求也就是息壤需求和蓝铁需求，然后让剩余的源矿流向它。当然因为灼重药都不用源，所以其实是全部的源矿给中电；蓝铁没有用到其他原料，那么它就是单纯地得到剩余的蓝铁。我们可以发现，每一种原料都对应着一种产物去使用其他产物用剩下的该原料，我们将其称为末端，比如在这里，灼铜使用重息壤用剩下的铜，灼铜是铜的末端；重息壤使用灼铜和中电用剩下的息壤，重息壤是息壤的末端；然后中电是源矿的末端，小药是蓝铁的末端。</p><p><span id="source-block-5CseafpFcCFziil8eb2h90"></span></p><h3 id="更复杂的末端" tabindex="-1">更复杂的末端 <a class="header-anchor" href="#更复杂的末端" aria-label="Permalink to &quot;更复杂的末端&quot;">​</a></h3><p>那么末端只能是一种产物吗？当然不是！比如在1.5智能最大毛产中，在赫铜未满仓时灼铜赫铜产出保持1：2，此时的铜的末端就是1：2的赫件和灼件了，只不过产券角度来说这样的铜末端不如纯灼铜的铜末端值钱</p><p><span id="source-block-bN9YKhSGeOTZu3Yp5K1Mm5"></span></p><h2 id="原视频模块讲解" tabindex="-1">原视频模块讲解 <a class="header-anchor" href="#原视频模块讲解" aria-label="Permalink to &quot;原视频模块讲解&quot;">​</a></h2><p><span id="source-block-SgLG4RYruAXSdwkboDc6uA"></span></p><h3 id="景玉谷" tabindex="-1">景玉谷 <a class="header-anchor" href="#景玉谷" aria-label="Permalink to &quot;景玉谷&quot;">​</a></h3><p>这是双核中容电池产线，消耗壤晶和源矿生产中容武陵电池；并且额外回收一条砂叶粉末，在主基地会用来生产剩下的半速电池</p><p>这是息壤产线，接入水后通过种植机循环产生足够植物，供给给12个洪炉生产息壤</p><p><span id="source-block-iUtARgwjRSvwMVlHrK4liC"></span></p><h3 id="主基地" tabindex="-1">主基地 <a class="header-anchor" href="#主基地" aria-label="Permalink to &quot;主基地&quot;">​</a></h3><p>这是剩余的中容电池产线，除了源矿之外还消耗景玉谷的中容电池产线回收的一条砂叶粉末和如果有的超库存传输的致密源石粉末，生产中容武陵电池。</p><p>这是赤铜精炼产线，消耗清水将赤铜矿精炼成赤铜块，并产生大量的污水。</p><p>这是三扩反一小反防爆仓壤晶产线，输入足量息壤、蓝铁粉末、污水、息壤液，生产壤晶。和常见的四扩反壤晶线和三扩反两小反壤晶线不同，我们将生产息壤液的反应池拿出来，把它和重息壤产线的反应池放在了一起，统一调度息壤液。</p><p>这是蓝铁粉末产线，用更多的取货口保证在蓝铁块空仓时有足够原料生产供壤晶线使用的蓝铁粉末。</p><p>这是小药产线，用蓝铁粉末产线用剩下的蓝铁块生产小药</p><p>这是加压分离芯产线，用更多的取货口保证在铜或者息壤空仓时也有足够原料用于生产分离芯。</p><p>这是息壤液化产线，其中一台反应池混产了小药用到的药液。</p><p>这是自适应息壤气产线，它在息壤气充足时会自发地停止生产以避免息壤液浪费，并且采用自适应震荡供料实现对任意的息壤液输入量做到0息壤液浪费。</p><p>这是自适应重息壤产线，它采用自适应震荡供料实现对任意息壤气输入量做到0息壤气浪费。</p><p>这是销毁模块，不同于常见的销毁最终产物的销毁模块，它销毁溢出的污水和溢出的赤铜块。当赤铜块爆仓时它销毁赤铜块保证壤晶产线仍然有足够的污水；当电池和壤晶都爆仓后，壤晶产线使用的污水大幅减少，它销毁溢出的污水保证一旁的赤铜精炼产线正常生产。</p><p>这是灼铜装备原件产线，因为灼铜装备元件可以用于制造其他装备原件生产的装备，所以不需要其他装备原件产线了。</p><p>这是赤铜打粉产线，产生的赤铜粉末将在应龙关被制作成灼铜零件和赫铜零件。</p><p><span id="source-block-jqE9qDVLl7hib7enWBjDYy"></span></p><h3 id="首墩" tabindex="-1">首墩 <a class="header-anchor" href="#首墩" aria-label="Permalink to &quot;首墩&quot;">​</a></h3><p>放置因为缺少水和惰气所以主基地塞不下的加压分离芯产线和赤铜精炼赤铜打粉产线。</p><p><span id="source-block-YkHPmnd7sMzC8RnByQFIqi"></span></p><h3 id="应龙关" tabindex="-1">应龙关 <a class="header-anchor" href="#应龙关" aria-label="Permalink to &quot;应龙关&quot;">​</a></h3><p>这是赤铜液化产线，两个扩容反应池用于混产赤铜气产线需要用到的息壤液。</p><p>这是自适应赤铜气产线，它采用自适应震荡供料实现对大范围的赤铜液输入量做到0息壤液浪费。完美的压缩</p><p>这是赫铜气产线，在惰气环境下使用分离芯将赤铜气提纯为赫铜气。</p><p>这是震荡酸环境自适应灼铜气产线，它采用自适应震荡供料实现对大范围的赫铜气输入量做到最少的酸液输入以节省气化这些酸液的息壤液，同时这台酸气息壤气混产的液气机同样采取自适应震荡供料实现酸气息壤气生产时的0息壤液浪费。</p><p>这是自动赫灼切换的自适应赫灼块产线，它采用自适应震荡供料实现对大范围的赫铜气/灼铜气输入量做到0息壤气浪费。同时，当赫铜块爆仓时，赫铜块会阻断流经断电反应池的液体，被阻断的液体会阻断赫铜气输入，而后该产线在清灰装置的辅助下全自动地将赫铜块生产切换为灼铜块生产。</p><p><span id="source-block-xQZEb7EUWaqy0tuIq0oY9L"></span></p><h2 id="未敲定的议题" tabindex="-1">未敲定的议题 <a class="header-anchor" href="#未敲定的议题" aria-label="Permalink to &quot;未敲定的议题&quot;">​</a></h2><p><span id="source-block-BwV0i64mm63Pdnc2Z3oOMH"></span></p><h2 id="文案-脚本讨论区" tabindex="-1">文案/脚本讨论区 <a class="header-anchor" href="#文案-脚本讨论区" aria-label="Permalink to &quot;文案/脚本讨论区&quot;">​</a></h2><p><span id="source-block-1RyfHoAVpOrOvSjtMXeTLE"></span></p><h3 id="_2026-9-19-22-43" tabindex="-1">2026.9.19 22:43 <a class="header-anchor" href="#_2026-9-19-22-43" aria-label="Permalink to &quot;2026.9.19 22:43&quot;">​</a></h3><p>框架：<br> 旧态到新态（增加铜）会发生什么——体现自动配平的迭代过程</p><p>↓</p><p>息壤供应不足会发生什么——表明非末端充分供料的必要性</p><p>↓</p><p>扩大旧态到新态的过程（新的旧态：仅重息壤 新的新态：加入灼直到铜壤配平）——更突出地表达灼是用剩下的铜</p><p><span id="source-block-JOxC2fD52yXIh4EYJhbbOd"></span></p><h3 id="_2026-9-14-20-58" tabindex="-1">2026.9.14 20:58 <a class="header-anchor" href="#_2026-9-14-20-58" aria-label="Permalink to &quot;2026.9.14 20:58&quot;">​</a></h3><p>为了方便，我们暂且将息壤和息壤气都当成息壤</p><p>要认识自动配平，我们不妨假设现在有一个赤铜矿没有拉满的账号，它目前的赤铜矿产能是420/min</p><p>为了使产券最多，我们要把赤铜、息壤、源矿、蓝铁做成灼铜零件、重息壤、中容武陵电池、芽针针剂</p><p>我们先关注灼铜零件和重息壤对赤铜和息壤的配平</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7da7429867a00f86.q90-f9c4bbb4c26b2f9e.webp" alt="讲解：自配平产线和自适应装置"></p><p>然后我们现在去把矿点开了，赤铜矿变多了！进行一个二元一次方程的求解，我们得到新的配平</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-af74318dad62164e.q90-585d5891a6d704b1.webp" alt="讲解：自配平产线和自适应装置"></p><p>灼铜变多了而重息壤变少了，欸，但是如果我们给灼铜零件提供的息壤没有完全跟上新的配平中灼铜对息壤的需求，那会发生什么呢</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f58e31a95e24c60a.q90-5492ff1c8c0a945c.webp" alt="讲解：自配平产线和自适应装置"></p><p>无法完全配平，剩下了赤铜没用上！因此我们需要对灼铜充分供应息壤，<br> 到底该怎么把优先供应灼铜的息壤但是铜不供应满形象地表达啊啊啊啊啊啊</p><p>君：你换个角度思考，铜供应不全→供应剩余赤铜，息壤的过量注入可以让工厂能够完全接收剩余赤铜，可以将其当做最初的【令机器激活】的物品而不是将其当做【反应物】。</p><p>产线目标：考虑以旧配平为初状态，新配平为末状态，初状态灼铜＞末状态灼铜，初状态重息壤＜末状态重息壤，由此可确认其需求迭代的增减性</p><p>对应的离散迭代过程：瞬时的赤铜增加，其必然去向为灼铜工厂，此时尝试消耗更多息壤，此时重息壤工厂接收的剩余息壤减少，对应赤铜（分离芯）消耗减少，剩余赤铜再次增多，此为一轮迭代，生成中间状态，灼铜工厂重新接收剩余赤铜，以前文相同的迭代方法逐渐降低剩余赤铜量直至趋近0。</p><p>其对应的连续过程为：重息壤产量逐渐降低，灼铜产量逐渐升高，很显然符合初状态→末状态的产物增减需求</p><p>产物最终敛散性：只需要解释这个迭代过程中，剩余赤铜变量 x 在 迭代轮次 n 趋近无穷时的极限为 0 ，迭代过程可以明显发现 x 关于 n 的函数为指数函数，在灼铜和重息壤的息壤与重息壤的优先级设定中，其底数小于 1 ，<s>读者自证不难</s>，详情可见自动配平相关理论（言：这一段假定的初状态向末状态的迭代可以用迭代过程可视化代替证明过程来表达结果是收敛的</p><p>因为多的铜要能进灼铜线所以铜不能是过量供应 因为铜过量供应就会让重息壤配不平息壤 因为我们要让灼铜和重息壤争抢每一份铜和息壤 我感觉这个迭代过程也要结合产线来说<br> 迭代过程指的是铜变多 灼铜变多 息壤变少 重息壤变少 又多出一点铜 然后循环往复直至所有铜和息壤都被用完并且只产出灼重，根据守恒律我们可以认为足够长的时间中灼重配平了铜壤</p><p>我已急哭</p><p>直接把这个迭代过程可视化？</p><p>然后也可视化如果不给灼铜充分供应息壤在迭代上的表现</p><p><span id="source-block-hyzbWvKvqI97NgRfXUOfrk"></span></p><h3 id="_2026-9-17-1-23" tabindex="-1">2026.9.17 1:23 <a class="header-anchor" href="#_2026-9-17-1-23" aria-label="Permalink to &quot;2026.9.17 1:23&quot;">​</a></h3><p>言：仅从两方面说？在旧状态向新状态的迭代中①如果灼铜的息壤供应不足，就吃不完铜，然后有铜剩下来，重息壤同理②灼铜在息壤供料充足时可以吃掉多余的铜，重息壤在铜供应充足时可以吃掉多余的息壤，最后用干净铜壤，而通过守恒律，消耗完铜壤而只产出灼重显然是配平成功了<br> 然后可视化这两个进程</p></div>',1)])])}const g=s(e,[["render",l]]);export{m as __pageData,g as default};
